from lab import *
r={'at':now(),'stage':'EX05 Follow-up: alternatives and exact origin','sources':{},'processes':rows("select c.ad_process_id,c.value,c.classname,c.isactive,coalesce(string_agg(p.columnname,',' order by p.seqno),'') from adempiere.ad_process c left join adempiere.ad_process_para p on c.ad_process_id=p.ad_process_id where lower(c.classname) like '%eveniment%' or (lower(c.classname) like '%corelare%' and lower(c.classname) like any(array['%comenz%','%preia%','%site%','%api%'])) group by 1,2,3,4 order by 2"),'triggers':rows("select tgname from pg_trigger where tgrelid='adempiere.eva_evenimentsite'::regclass and not tgisinternal;"),'source_flags':rows("select eva_sursa,eva_tenant,eva_platforma,eva_sursaproprie,eva_vanzarionline,eva_scrierepermisa,eva_ultimaactualizare from adempiere.eva_sursasite where ad_client_id=11 order by 1"),'origin_sql':rows("select s.eva_idextern,s.eva_nrcomanda,s.eva_comandasite_id,s.eva_sursa,s.eva_proprie,s.eva_starevalidare,coalesce(s.eva_totalcomanda,0),s.c_order_id,s.m_inout_id,s.c_invoice_id,(select count(*) from adempiere.eva_comandasitelinie l where l.eva_comandasite_id=s.eva_comandasite_id) from adempiere.eva_comandasite s where s.eva_sursa in ('EX05A','EX05B') order by s.eva_sursa,s.eva_nrcomanda"),'reference':'No IDs artificially assigned between staging and C_Order.'}
save('native-ex05-alt.json',r);print(json.dumps({'ps':r['processes'],'flags':r['source_flags'],'origins':r['origin_sql'][:1]},ensure_ascii=False))

